import React, { useEffect, useState } from 'react'
import FoodOrdersTable from './FoodOrdersTable'

import useApi from '../../../hooks/useApi'
import { useNavigate } from 'react-router-dom';
import FoodFormModal from './FoodFormModal';
import { ToastContainer, toast } from "react-toastify";
import restaurantApi from '../../../api/restaurants/restaurantApi';

const columns = [
  { name: "Reference", uid: "document_number" },
  { name: "Amount (KES)", uid: "order_total_amount" },
  { name: "Table", uid: "table_title" },
  { name: "Attendant", uid: "owner_title" },
  { name: "Date", uid: "created" },
  { name: "Is Paid", uid: "is_paid" },
  { name: "Is Served", uid: "is_served" },
  { name: "Actions", uid: "actions" },
];


function FoodList() {
    const [openEditModal, setopenEditModal] = useState(false)

    const navigate = useNavigate()
    const [menu, setMenu] = useState()
    const [menus, setMenus] = useState([])
    const [data, setdata] = useState([])
    const [updated, setUpdated] = useState(false)
    const [modalTitle, setmodalTitle] = useState("")
    const restaurantActionsApi = useApi(restaurantApi.restaurantAction)

    const getBranchFoodOrders = async () => {
        await restaurantActionsApi.request({
            "action": "GetUserFoodOrders"

        })
    }
    useEffect(() => {
        setdata(menus)
    }, [menus])

    const handleFilter = (e) => {

        console.log('eeeee', e)
        const search_param = e

        if (menus && menus.length > 0 && search_param && search_param !== '') {
            setdata(menus.filter((x) => x.title.toLowerCase().includes(search_param)));
        } else {
            setdata(menus);
        }
    };

    useEffect(() => {
        getBranchFoodOrders()
    }, [])

    useEffect(() => {

  
              getBranchFoodOrders()
        
      
    }, [updated])

    const handleEditAction = (item) => {

        setopenEditModal(true)
        setMenu(item)
        setmodalTitle(`EDIT ${item.title}`)
        setUpdated(false)

    }

    const handleAddAction = () => {
        setopenEditModal(true)
        setmodalTitle("Add new food Item")
        setMenu(null)
    }
    const handleDetailsAction = (item) => {


        navigate(`/routes/details/${item.id}`, {
            state: {
                'item': item
            }
        })
    }
    const handleDeleteAction = (item) => {
        console.log('Item', item)
        navigate(`/routes/delete/${item.id}`)
    }



    useEffect(() => {

        if (restaurantActionsApi.data && restaurantActionsApi.data.length) {

            setMenus(restaurantActionsApi.data)
        }

        if (restaurantActionsApi.data && restaurantActionsApi.data.response_message && restaurantActionsApi.data.response_code===1) {

            toast.error(restaurantActionsApi.data.response_message)
        }

        if (restaurantActionsApi.data && restaurantActionsApi.data.response_message && restaurantActionsApi.data.response_code===0) {

            toast.success(restaurantActionsApi.data.response_message)
        }
       
        console.log("transportActionsApi.data",restaurantActionsApi.data)
    }, [restaurantActionsApi.data])

    useEffect(() => {
        getBranchFoodOrders()
    }, [updated])

    return (
        <div>
        <ToastContainer position="bottom-center" theme="colored" />
            {openEditModal && <FoodFormModal openEditModal={openEditModal} setopenEditModal={setopenEditModal} item={menu} updated={updated} setUpdated={setUpdated} modalTitle={modalTitle} />}
            <FoodOrdersTable data={data} columns={columns}
                editAction={handleEditAction} detailsAction={handleDetailsAction} deleteAction={handleDeleteAction} addAction={handleAddAction} handleFilter={handleFilter} />
        </div>
    )
}

export default FoodList